import type { ReactNode, Ref } from 'react'
import { NumberField } from '@base-ui/react/number-field'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import {
  InputField,
  boxClass,
  inputStyles,
  type InputSize,
  type ValidationState,
} from './InputField'
import styles from './NumberInput.module.css'

export interface NumberInputProps {
  ref?: Ref<HTMLInputElement>
  value?: number | null
  defaultValue?: number
  /** The spec's `onChange`. `null` when the field is emptied. */
  onValueChange?: (value: number | null) => void
  min?: number
  max?: number
  step?: number
  /** Decimal places shown and accepted. */
  precision?: number
  label?: ReactNode
  helperText?: ReactNode
  validationState?: ValidationState
  size?: InputSize
  isFullWidth?: boolean
  name?: string
  placeholder?: string
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  id?: string
  className?: string
  'aria-label'?: string
}

export function NumberInput({
  ref,
  label,
  helperText,
  validationState,
  size = 'md',
  isFullWidth,
  precision,
  name,
  placeholder,
  disabled,
  required,
  className,
  onValueChange,
  id,
  'aria-label': ariaLabel,
  ...props
}: NumberInputProps) {
  return (
    <InputField
      label={label}
      helperText={helperText}
      validationState={validationState}
      required={required}
      disabled={disabled}
      name={name}
      isFullWidth={isFullWidth}
      className={className}
    >
      <NumberField.Root
        {...props}
        id={id}
        required={required}
        format={
          precision === undefined
            ? undefined
            : { minimumFractionDigits: precision, maximumFractionDigits: precision }
        }
        onValueChange={onValueChange && ((next) => onValueChange(next))}
      >
        <NumberField.Group className={cn(boxClass(size), styles.group, styles[size])}>
          <NumberField.Input
            ref={ref}
            placeholder={placeholder}
            aria-label={ariaLabel}
            className={cn(inputStyles.control, styles.input)}
          />
          {/* Base UI names these "Decrease" and "Increase" for assistive tech. */}
          <NumberField.Decrement className={styles.step}>
            <Icon name="minus" />
          </NumberField.Decrement>
          <NumberField.Increment className={styles.step}>
            <Icon name="plus" />
          </NumberField.Increment>
        </NumberField.Group>
      </NumberField.Root>
    </InputField>
  )
}

/* The stepper buttons float inside the field: no divider, a small inset
   from the end, and a fill only on hover. */
.group.group {
  gap: 2px;
  padding-inline-end: var(--space-1);
}

.input {
  font-variant-numeric: tabular-nums;
}

/* Square, 8px shorter than the field: 24px in md, 16px in sm. */
.step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  inline-size: calc(var(--field-size) - 8px);
  block-size: calc(var(--field-size) - 8px);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--muted-foreground);
  font-size: var(--space-4);
  cursor: var(--cursor-button);
  transition:
    background-color 150ms,
    color 150ms;
}

.sm .step {
  font-size: var(--space-3);
}

.step:hover {
  background: var(--accent);
  color: var(--foreground);
}

.step:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 0;
}

.step:disabled,
.step[data-disabled] {
  cursor: var(--cursor-disabled);
  opacity: 0.5;
}

.step:disabled:hover,
.step[data-disabled]:hover {
  background: transparent;
  color: var(--muted-foreground);
}

/* On touch they widen to 44px, the only direction they can grow without
   overlapping the input or each other. */
@media (pointer: coarse) {
  .step {
    min-inline-size: 44px;
  }
}
